import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"16、【豫】 坤下震上","description":"周易口诀义 - 16、【豫】 坤下震上","frontmatter":{"title":"16、【豫】 坤下震上","description":"周易口诀义 - 16、【豫】 坤下震上"},"headers":[],"relativePath":"zh/classics/koujueyi/018.md","filePath":"zh/classics/koujueyi/018.md"}'),r={name:"zh/classics/koujueyi/018.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_16、【豫】-坤下震上" tabindex="-1">16、【豫】 坤下震上 <a class="header-anchor" href="#_16、【豫】-坤下震上" aria-label="Permalink to “16、【豫】 坤下震上”">​</a></h1><p>彖曰：「豫」，刚应而志行，顺以动，豫。豫顺以动，故天地如之，而况「建侯行师」乎！天地以顺动，故日月不过而四时不忒；圣人以顺动，则刑罚清而民服。豫之时义大矣哉！</p><p>象曰：雷出地奋，「豫」。先王以作乐崇德，殷荐之上帝，以配祖考。</p><p>初六：鸣豫，凶。</p><p>象曰：「初六鸣豫」，志穷凶也。</p><p>六二：介于石，不终日，贞吉。</p><p>象曰：「不终日贞吉」，以中正也。</p><p>六三：盱豫，悔，迟有悔。</p><p>象曰：「盱豫」有「悔」，位不当也。</p><p>九四：由豫，大有得。勿疑，朋盍簪。</p><p>象曰：「由豫大有得」，志大行也。</p><p>六五：贞疾，恒不死。</p><p>象曰：「六五贞疾」，乘刚也。「恒不死」，中未亡也。</p><p>上六：冥豫成，有渝，无咎。</p><p>象曰：「冥豫」在上，何可长也。</p><p>无（四库全书标明，摘录时缺豫、随、无妄、大壮、晋、睽、蹇、解、中孚八卦）</p>',16)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
